contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        require(caller != address(0));
        require(newOwner != address(0));

        address initialOwner = c.owner();

        bool reverted;
        if (caller == initialOwner) {
            c.transferOwnership(newOwner);
            reverted = false;
        } else {
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        address finalOwner = c.owner();

        if (caller == initialOwner) {
            assert(!reverted && finalOwner == newOwner);
        } else {
            assert(reverted && finalOwner == initialOwner);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, bool asOwner) public {
        require(newOwner != address(0));

        address initialOwner = c.owner();
        address caller = asOwner ? initialOwner : address(0xdeadbeef);

        bool reverted;
        if (caller == initialOwner) {
            c.transferOwnership(newOwner);
            reverted = false;
        } else {
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        address finalOwner = c.owner();

        assert(
            (caller == initialOwner && !reverted && finalOwner == newOwner) ||
            (caller != initialOwner && reverted && finalOwner == initialOwner)
        );
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, bool forceRevert) public {
        address before = c.owner();
        require(newOwner != address(0));
        require(forceRevert || newOwner != before);

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address after = c.owner();

        assert(
            (forceRevert && reverted && after == before) ||
            (!forceRevert && !reverted && after == newOwner)
        );
    }
}

