contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, address caller2) public {
        c.transferOwnership(newOwner);
        address afterFirst = c.owner();

        bool secondIsSelf = caller2 == address(this);
        bool reverted2;
        if (!secondIsSelf) {
            // caller2 is not this contract; cannot drive a call as caller2, so only
            // reason about the observable owner after this contract's own call.
            reverted2 = false;
        } else {
            c.transferOwnership(caller2);
            reverted2 = false;
        }

        address afterSecond = c.owner();

        assert(afterFirst == newOwner && (!secondIsSelf || afterSecond == caller2));
    }
}

contract InvMutTest {
