        require(firstOwner != secondOwner);

        c.transferOwnership(firstOwner);
        require(c.owner() == firstOwner);

        bool firstOwnerCallSucceeded;
        try c.owned() {
            firstOwnerCallSucceeded = true;
        } catch {
            firstOwnerCallSucceeded = false;
        }

        c.transferOwnership(secondOwner);

        assert(!firstOwnerCallSucceeded && c.owner() == secondOwner);
    }
}

