contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, address thirdParty) public {
        address originalOwner = c.owner();

        bool firstTransferReverted;
        try c.transferOwnership(newOwner) {
            firstTransferReverted = false;
        } catch {
            firstTransferReverted = true;
        }

        if (!firstTransferReverted) {
            address ownerAfterFirst = c.owner();
            bool secondTransferReverted;
            try c.transferOwnership(thirdParty) {
                secondTransferReverted = false;
            } catch {
                secondTransferReverted = true;
            }
            assert(
                (ownerAfterFirst == newOwner) &&
                !secondTransferReverted &&
                (c.owner() == thirdParty)
            );
        } else {
            assert(c.owner() == originalOwner);
        }
    }
}

